insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_feature_8','feature','noun','a typical or noticeable part or quality of a design, product or place','[{"senseId":"feature_8_1","meaning":"a typical or noticeable part or quality of a design, product or place","acceptedParaphrases":["noticeable part","typical quality"],"masteryContexts":[{"contextId":"u8_11_feature_8_meaning","text":"The phone’s best feature is a battery that lasts for three days.","meaning":"an important or noticeable part of a product","wrongMeanings":["the main problem with a product","the shop that sells a product","the cost of repairing a product"]},{"contextId":"u8_11_feature_8_paraphrase","text":"Large windows are a typical feature of the architect’s buildings.","meaning":"a part or quality that is often seen","wrongMeanings":["a mistake that is often made","a material that is often wasted","a rule that is often broken"]}],"situationDistractors":["A worker took the lift to the fifth floor.","A manager left the office early to catch a train.","A cleaner swept the floor of the empty canteen.","A trainee filled in a form on her first day.","A delivery van arrived late because of heavy traffic.","Two colleagues shared an umbrella on the way to work."],"gapDistractors":[{"contextId":"u8_11_feature_8_gap_1","answer":"feature","wrong":["response","minority","source"]},{"contextId":"u8_11_feature_8_gap_2","answer":"feature","wrong":["response","assignment","instructor"]},{"contextId":"u8_11_feature_8_gap_3","answer":"feature","wrong":["response","minority","humanity"]}],"spellingErrors":["featur","feture","feeature","featuer","fearture","feachure"],"masteryPassages":[{"passageId":"u8_11_feature_8_passage_1","contextId":"u8_11_feature_8_gap_1","text":"The new phone looks just like the old model. Its most useful new ____, however, is a camera that works well in the dark.","answer":"feature"},{"passageId":"u8_11_feature_8_passage_2","contextId":"u8_11_feature_8_gap_2","text":"Visitors always notice the huge glass staircase in the hotel lobby. It is the building’s most famous ____, and it appears on all the postcards.","answer":"feature"}],"contextDependentParaphrases":[],"wrongParaphrases":["hidden fault","final price","original owner"],"misleadingDistractors":["the price of a product in the shops","a mistake found in a finished design","the person who designs a product"],"teacherNote":"Noun: a typical or noticeable part or quality of a design, product or place (a safety feature, a key feature). Unit 8 uses it for designs and products at work; Unit 2 taught the same core sense in a travel context. As a verb (the film features...) it means to include as an important part, which is not taught here."}]'::jsonb,'[]'::jsonb,'["a key feature","a safety feature","a special feature of the design"]'::jsonb,'live'),
('vocab_humanity','humanity','noun','all the people in the world, thought of together','[{"senseId":"humanity_1","meaning":"all the people in the world, thought of together","acceptedParaphrases":["all people","the human race"],"masteryContexts":[{"contextId":"u8_12_humanity_meaning","text":"The invention of the vaccine was one of the greatest achievements in the history of humanity.","meaning":"all people in the world, over time","wrongMeanings":["the people of one small country","the scientists who work in medicine","the doctors who give treatment"]},{"contextId":"u8_12_humanity_paraphrase","text":"The engineer said she wanted her designs to help humanity, not just to make money.","meaning":"people everywhere","wrongMeanings":["her own family","her company’s customers","the people she works with"]}],"situationDistractors":["A manager gave a gift to one worker who had helped her.","A shop owner lowered prices for customers in her street.","A coach helped one player improve his kicking.","A nurse cared for a single patient overnight.","A teacher helped three students with their homework.","A builder repaired the roof of his neighbour’s house."],"gapDistractors":[{"contextId":"u8_12_humanity_gap_1","answer":"humanity","wrong":["packaging","publicity","architecture"]},{"contextId":"u8_12_humanity_gap_2","answer":"humanity","wrong":["packaging","architecture","publicity"]},{"contextId":"u8_12_humanity_gap_3","answer":"humanity","wrong":["packaging","publicity","availability"]}],"spellingErrors":["humanaty","humannity","humanitey","humanety","humanitty","hummanity"],"wordFamilyForms":[{"form":"humanity","partOfSpeech":"noun","example":"Scientists are working to protect the future of humanity.","pedagogicallyUseful":true},{"form":"human","partOfSpeech":"adjective","example":"Every machine in the factory is checked by a human inspector as well as a computer.","pedagogicallyUseful":true,"altExample":"Robots can do many jobs, but some work still needs a human touch."},{"form":"humanitarian","partOfSpeech":"adjective","example":"The charity sends humanitarian aid to countries hit by floods.","pedagogicallyUseful":true,"altExample":"Doctors flew to the area on a humanitarian mission."}],"masteryPassages":[{"passageId":"u8_12_humanity_passage_1","contextId":"u8_12_humanity_gap_1","text":"Some inventions change life for everyone on the planet. The internet, for example, has changed the way that the whole of ____ communicates and learns.","answer":"humanity"},{"passageId":"u8_12_humanity_passage_2","contextId":"u8_12_humanity_gap_2","text":"The space agency sent a golden record into space. It carried music and greetings from ____, in case anyone out there ever finds it.","answer":"humanity"}],"contextDependentParaphrases":[],"wrongParaphrases":["local people","young people","rich people"],"misleadingDistractors":["the people who live in one country","a group of experts who study people","the rules that people must obey"],"teacherNote":"Noun: all people in the world, considered together (benefit humanity, the future of humanity). Boundary: humanity can also mean kindness towards others (he showed great humanity); Unit 8 teaches the \"all people\" sense. The adjectives human and humanitarian are taught in the Word Family pathway."}]'::jsonb,'["human","humanitarian"]'::jsonb,'["the whole of humanity","benefit humanity","the future of humanity"]'::jsonb,'live'),
('vocab_impact','impact','noun','a strong effect that something has on a situation or a person','[{"senseId":"impact_1","meaning":"a strong effect that something has on a situation or a person","acceptedParaphrases":["strong effect","powerful influence"],"masteryContexts":[{"contextId":"u8_13_impact_meaning","text":"The factory closing had a serious impact on the small town, where many families lost their income.","meaning":"a strong effect on a place","wrongMeanings":["a short visit to a place","a full report on a place","a long journey to a place"]},{"contextId":"u8_13_impact_paraphrase","text":"The trainer’s advice had a big impact on how confident the new staff felt.","meaning":"a strong influence on people","wrongMeanings":["a quick test of people","a long talk to people","a small gift for people"]}],"situationDistractors":["A worker forgot to bring her umbrella, but it did not rain.","A new poster was put up in the corridor, but nobody noticed it.","The manager changed the font on a form, and nothing else happened.","A colleague sent an email that nobody opened.","A small change to the menu made no difference to sales.","The office clock was moved to a different wall."],"gapDistractors":[{"contextId":"u8_13_impact_gap_1","answer":"impact","wrong":["response","source","feature"]},{"contextId":"u8_13_impact_gap_2","answer":"impact","wrong":["source","minority","feature"]},{"contextId":"u8_13_impact_gap_3","answer":"impact","wrong":["packaging","assignment","response"]}],"spellingErrors":["impackt","impakt","inpact","impect","imppact","impacct"],"masteryPassages":[{"passageId":"u8_13_impact_passage_1","contextId":"u8_13_impact_gap_1","text":"When the new motorway opened, the small shops in the village lost most of their customers. The road had a serious ____ on local businesses.","answer":"impact"},{"passageId":"u8_13_impact_passage_2","contextId":"u8_13_impact_gap_2","text":"Our science teacher was so enthusiastic that half the class chose to study science at university. She had a huge ____ on our lives.","answer":"impact"}],"contextDependentParaphrases":[],"wrongParaphrases":["short report","clear reason","fixed rule"],"misleadingDistractors":["a short report about an event","a reason for making a decision","a rule that controls a situation"],"teacherNote":"Noun: a strong effect (have an impact on, a big impact). Boundary: impact also means the force of one thing hitting another (on impact); Unit 8 teaches the effect sense. No family is taught: the verb impact shares the spelling and impactful is informal."}]'::jsonb,'[]'::jsonb,'["have an impact on","a huge impact","the impact of something on something"]'::jsonb,'live'),
('vocab_ingredients_8','ingredients','noun','the foods or substances that are combined to make a product, especially a food','[{"senseId":"ingredients_8_1","meaning":"the foods or substances that are combined to make a product, especially a food","acceptedParaphrases":["foods mixed to make a product","things combined in a recipe"],"masteryContexts":[{"contextId":"u8_14_ingredients_8_meaning","text":"The company uses only natural ingredients, so its juices contain no added sugar or colours.","meaning":"the things that a product is made from","wrongMeanings":["the machines that a product is made on","the shops that a product is sold in","the boxes that a product is packed in"]},{"contextId":"u8_14_ingredients_8_paraphrase","text":"By law, the packet must list all the ingredients, starting with the largest amount.","meaning":"the foods combined in a product","wrongMeanings":["the prices charged for a product","the places where a product is made","the dates when a product was made"]}],"situationDistractors":["A driver loaded boxes of biscuits onto a lorry.","A shop assistant put price labels on tins of soup.","A cleaner washed the factory floor after the night shift.","A manager counted how many packets were sold last week.","A designer chose a new colour for the cereal box.","A customer paid for her shopping at the till."],"gapDistractors":[{"contextId":"u8_14_ingredients_8_gap_1","answer":"ingredients","wrong":["facilities","regulations","structures"]},{"contextId":"u8_14_ingredients_8_gap_2","answer":"ingredients","wrong":["inspectors","facilities","structures"]},{"contextId":"u8_14_ingredients_8_gap_3","answer":"ingredients","wrong":["regulations","structures","inspectors"]}],"spellingErrors":["ingrediants","ingreedients","ingredents","ingridients","ingredientz","ingredeints"],"masteryPassages":[{"passageId":"u8_14_ingredients_8_passage_1","contextId":"u8_14_ingredients_8_gap_1","text":"The new energy bar contains only five ____: dates, oats, nuts, honey and a little salt. There are no artificial colours or flavours.","answer":"ingredients"},{"passageId":"u8_14_ingredients_8_passage_2","contextId":"u8_14_ingredients_8_gap_2","text":"Lucy is allergic to nuts, so she always reads the back of the packet. She checks the list of ____ before she buys any snack.","answer":"ingredients"}],"contextDependentParaphrases":[],"wrongParaphrases":["machines used to make a product","boxes used to sell a product","people paid to sell a product"],"misleadingDistractors":["the machines used to cook food in a factory","the boxes and wrappers that food is sold in","the people who test new foods"],"teacherNote":"Plural noun: the foods or substances combined to make a product (natural ingredients, a list of ingredients). Unit 8 uses it in food manufacturing and product development; Unit 3 taught it for cooking a dish. No family is taught: the singular ingredient is the same word."}]'::jsonb,'[]'::jsonb,'["natural ingredients","a list of ingredients","fresh ingredients"]'::jsonb,'live'),
('vocab_innovation','innovation','noun','a new idea, method or product, or the process of creating new things','[{"senseId":"innovation_1","meaning":"a new idea, method or product, or the process of creating new things","acceptedParaphrases":["a new idea or method","the creating of new things"],"masteryContexts":[{"contextId":"u8_15_innovation_meaning","text":"The touch screen was an innovation that changed the way people use phones.","meaning":"a new idea or product","wrongMeanings":["an old product that people liked","a broken product that was returned","a cheap copy of a product"]},{"contextId":"u8_15_innovation_paraphrase","text":"The company encourages innovation by giving staff one day a week to work on their own ideas.","meaning":"the creating of new ideas and methods","wrongMeanings":["the following of fixed rules","the cutting of costs","the copying of others"]}],"situationDistractors":["A worker followed the same steps she had used for twenty years.","A factory copied a design that another company had made years ago.","A manager told staff to keep doing things the old way.","A shop sold the same products it had sold since 1950.","A cook made the soup exactly as her grandmother had done.","A clerk filed papers in the same cabinet as always."],"gapDistractors":[{"contextId":"u8_15_innovation_gap_1","answer":"innovation","wrong":["response","minority","assignment"]},{"contextId":"u8_15_innovation_gap_2","answer":"innovation","wrong":["minority","humanity","wellbeing"]},{"contextId":"u8_15_innovation_gap_3","answer":"innovation","wrong":["minority","humanity","architecture"]}],"spellingErrors":["inovation","innovasion","innovaton","inovvation","innovatian","innovashun"],"wordFamilyForms":[{"form":"innovation","partOfSpeech":"noun","example":"The company has a reputation for innovation in design.","pedagogicallyUseful":true},{"form":"innovate","partOfSpeech":"verb","example":"Businesses must innovate if they want to stay ahead.","pedagogicallyUseful":true,"altExample":"Small companies often innovate faster than large ones."},{"form":"innovative","partOfSpeech":"adjective","example":"The architect is famous for her innovative use of glass.","pedagogicallyUseful":true,"altExample":"The school won an award for its innovative science lessons."}],"masteryPassages":[{"passageId":"u8_15_innovation_passage_1","contextId":"u8_15_innovation_gap_1","text":"Twenty years ago, nobody paid for coffee with a phone. Contactless payment was a clever ____ that is now part of everyday life.","answer":"innovation"},{"passageId":"u8_15_innovation_passage_2","contextId":"u8_15_innovation_gap_2","text":"The company used to make the same toys every year. The new director wanted more ____, so she asked the designers to bring her fresh ideas every month.","answer":"innovation"}],"contextDependentParaphrases":[],"wrongParaphrases":["an old habit or rule","a copied design or plan","a lost chance or offer"],"misleadingDistractors":["an old method that is still used","a copy of another company’s product","a rule that stops change"],"teacherNote":"Noun: a new idea, method or product, or the act of introducing new things (technological innovation, encourage innovation). Boundary: an invention is a completely new thing that someone has made; an innovation can also be a new way of improving something that already exists. The verb innovate and the adjective innovative are taught in the Word Family pathway."}]'::jsonb,'["innovate","innovative"]'::jsonb,'["technological innovation","encourage innovation","a major innovation"]'::jsonb,'live'),
('vocab_inspiration','inspiration','noun','a person or thing that gives you new ideas or makes you want to do something','[{"senseId":"inspiration_1","meaning":"a person or thing that gives you new ideas or makes you want to do something","acceptedParaphrases":["source of ideas","something that makes you want to create"],"masteryContexts":[{"contextId":"u8_16_inspiration_meaning","text":"The designer found inspiration for her new fabrics in the colours of the desert.","meaning":"ideas that come from something","wrongMeanings":["money that comes from something","problems that come from something","rules that come from something"]},{"contextId":"u8_16_inspiration_paraphrase","text":"Her first coach was a real inspiration, and she still remembers his advice.","meaning":"a person who makes you want to do well","wrongMeanings":["a person who makes you feel afraid","a person who checks your mistakes","a person who pays for your training"]}],"situationDistractors":["A designer copied an old pattern exactly from a book.","A worker felt bored and stared at the empty page.","A manager signed some forms without reading them.","An engineer measured the length of a pipe.","A cleaner switched off the lights at the end of the day.","A trainee waited for the bus in the rain."],"gapDistractors":[{"contextId":"u8_16_inspiration_gap_1","answer":"inspiration","wrong":["response","assignment","publicity"]},{"contextId":"u8_16_inspiration_gap_2","answer":"inspiration","wrong":["assignment","innovation","impact"]},{"contextId":"u8_16_inspiration_gap_3","answer":"inspiration","wrong":["response","employment","packaging"]}],"spellingErrors":["inspirasion","inspriation","insperation","inspiraton","inspirashun","inspiratian"],"wordFamilyForms":[{"form":"inspiration","partOfSpeech":"noun","example":"Nature is a great source of inspiration for many artists.","pedagogicallyUseful":true},{"form":"inspire","partOfSpeech":"verb","example":"Good teachers inspire their students to work hard.","pedagogicallyUseful":true,"altExample":"The film may inspire young people to study engineering."},{"form":"inspiring","partOfSpeech":"adjective","example":"The speaker told an inspiring story about starting her own business.","pedagogicallyUseful":true,"altExample":"Her speech at the awards ceremony was truly inspiring."}],"masteryPassages":[{"passageId":"u8_16_inspiration_passage_1","contextId":"u8_16_inspiration_gap_1","text":"Before writing her first song, Ana spent weeks walking by the sea. The sound of the waves gave her the ____ she needed, and the song was finished in a day.","answer":"inspiration"},{"passageId":"u8_16_inspiration_passage_2","contextId":"u8_16_inspiration_gap_2","text":"Many people admire the doctor who started the free clinic. She is an ____ to young people who want to help others.","answer":"inspiration"}],"contextDependentParaphrases":[],"wrongParaphrases":["source of money","cause of problems","list of rules"],"misleadingDistractors":["a rule that tells you what to do","a mistake that you learn from","a reward for finishing a task"],"teacherNote":"Noun: a person or thing that gives you ideas or makes you want to do something (the inspiration for, a source of inspiration). Boundary: inspiration is what starts the idea; motivation is the reason you keep working. The verb inspire and the adjective inspiring are taught in the Word Family pathway."}]'::jsonb,'["inspire","inspiring"]'::jsonb,'["a source of inspiration","the inspiration for something","find inspiration"]'::jsonb,'live'),
('vocab_inspectors','inspectors','noun','officials whose job is to check that rules and standards are being followed','[{"senseId":"inspectors_1","meaning":"officials whose job is to check that rules and standards are being followed","acceptedParaphrases":["officials who check standards","people who examine places for problems"],"masteryContexts":[{"contextId":"u8_17_inspectors_meaning","text":"The factory was closed after inspectors found that the fire exits were blocked.","meaning":"officials who check safety","wrongMeanings":["workers who build fire exits","customers who complain about a factory","managers who own a factory"]},{"contextId":"u8_17_inspectors_paraphrase","text":"School inspectors watched several lessons and then wrote a report on the quality of teaching.","meaning":"officials who judge standards","wrongMeanings":["parents who help in lessons","students who are training to teach","cleaners who work after school"]}],"situationDistractors":["A builder laid bricks for a new wall.","A chef cooked dinner for a large group of guests.","A shop assistant helped a customer choose a jacket.","A driver delivered fresh bread to a café.","A designer drew a new logo for a bank.","A farmer picked apples in her orchard."],"gapDistractors":[{"contextId":"u8_17_inspectors_gap_1","answer":"inspectors","wrong":["facilities","regulations","structures"]},{"contextId":"u8_17_inspectors_gap_2","answer":"inspectors","wrong":["ingredients","structures","facilities"]},{"contextId":"u8_17_inspectors_gap_3","answer":"inspectors","wrong":["regulations","ingredients","elements"]}],"spellingErrors":["inspecters","inspectros","inpectors","inspektors","insspectors","inspectores"],"wordFamilyForms":[{"form":"inspectors","partOfSpeech":"noun","example":"The inspectors spent two days checking the new hospital.","pedagogicallyUseful":true},{"form":"inspect","partOfSpeech":"verb","example":"A mechanic will inspect the brakes before the bus leaves.","pedagogicallyUseful":true,"altExample":"Officials will inspect the bridge after the storm."},{"form":"inspection","partOfSpeech":"noun","example":"The factory passed its safety inspection with no problems.","pedagogicallyUseful":true,"altExample":"The restaurant was closed after a surprise inspection."}],"masteryPassages":[{"passageId":"u8_17_inspectors_passage_1","contextId":"u8_17_inspectors_gap_1","text":"The owner of the café cleaned the kitchen all night. She knew that the ____ were coming the next morning to check whether it met the rules on hygiene.","answer":"inspectors"},{"passageId":"u8_17_inspectors_passage_2","contextId":"u8_17_inspectors_gap_2","text":"Two officials arrived at the building site with clipboards. The ____ looked at every ladder and scaffold and wrote down anything that was unsafe.","answer":"inspectors"}],"contextDependentParaphrases":[],"wrongParaphrases":["workers who build machines","people who sell products","students who learn trades"],"misleadingDistractors":["workers who build new machines","people who sell products to shops","teachers who train new staff"],"teacherNote":"Plural noun: officials whose job is to check that places, products or work meet rules and standards (safety inspectors, food inspectors). Boundary: inspectors check and report; they do not usually fix the problems themselves. The verb inspect and the noun inspection are taught in the Word Family pathway."}]'::jsonb,'["inspect","inspection"]'::jsonb,'["safety inspectors","food inspectors","a visit from inspectors"]'::jsonb,'live'),
('vocab_instructor','instructor','noun','a person whose job is to teach a practical skill, such as driving or swimming','[{"senseId":"instructor_1","meaning":"a person whose job is to teach a practical skill, such as driving or swimming","acceptedParaphrases":["teacher of a practical skill","person who teaches a skill"],"masteryContexts":[{"contextId":"u8_18_instructor_meaning","text":"The swimming instructor stood in the water and showed the children how to kick their legs.","meaning":"a person who teaches a practical activity","wrongMeanings":["a person who guards the swimming pool","a person who cleans the swimming pool","a person who sells tickets at the pool"]},{"contextId":"u8_18_instructor_paraphrase","text":"After passing the course, Ben became a qualified diving instructor in Egypt.","meaning":"someone paid to teach a skill","wrongMeanings":["someone paid to repair equipment","someone paid to check safety","someone paid to sell holidays"]}],"situationDistractors":["A man read a book about cars on the train.","A girl practised the piano alone in her room.","A mechanic repaired a broken engine.","A lifeguard watched the swimmers from a tall chair.","A shop assistant sold a pair of skis.","A receptionist booked a tennis court for a customer."],"gapDistractors":[{"contextId":"u8_18_instructor_gap_1","answer":"instructor","wrong":["nutritionist","scientist","landscape"]},{"contextId":"u8_18_instructor_gap_2","answer":"instructor","wrong":["nutritionist","scientist","director"]},{"contextId":"u8_18_instructor_gap_3","answer":"instructor","wrong":["scientist","engineer","operator"]}],"spellingErrors":["instructer","instrucktor","insturctor","instractor","instructior","instuctor"],"wordFamilyForms":[{"form":"instructor","partOfSpeech":"noun","example":"The instructor showed us how to use the climbing ropes.","pedagogicallyUseful":true},{"form":"instruct","partOfSpeech":"verb","example":"The manager will instruct new staff on how to use the till.","pedagogicallyUseful":true,"altExample":"Pilots instruct passengers to fasten their seat belts."},{"form":"instructions","partOfSpeech":"noun","example":"Read the instructions carefully before you use the machine.","pedagogicallyUseful":true,"altExample":"The instructions for the printer were in five languages."}],"masteryPassages":[{"passageId":"u8_18_instructor_passage_1","contextId":"u8_18_instructor_gap_1","text":"Before Nadia could take her test, she needed twenty driving lessons. Her ____ sat beside her and told her when to brake and when to turn.","answer":"instructor"},{"passageId":"u8_18_instructor_passage_2","contextId":"u8_18_instructor_gap_2","text":"The climbing centre will not let beginners on the wall alone. An ____ checks their ropes and teaches them how to hold on safely.","answer":"instructor"}],"contextDependentParaphrases":[],"wrongParaphrases":["seller of sports equipment","checker of safety rules","owner of a sports club"],"misleadingDistractors":["a person who checks that rules are followed","a person who manages a large company","a person who writes instructions for machines"],"teacherNote":"Noun: a person who teaches a practical skill or activity (a driving instructor, a fitness instructor). Boundary: an instructor teaches a skill or activity; a trainer usually improves the skills of staff or athletes over time; a teacher works with school subjects. The verb instruct and the noun instructions are taught in the Word Family pathway."}]'::jsonb,'["instruct","instructions"]'::jsonb,'["a driving instructor","a qualified instructor","a fitness instructor"]'::jsonb,'live'),
('vocab_launched','launched','verb','started selling a new product or started a new project or activity','[{"senseId":"launched_1","meaning":"started selling a new product or started a new project or activity","acceptedParaphrases":["introduced to the public","started selling"],"masteryContexts":[{"contextId":"u8_19_launched_meaning","text":"The charity launched a campaign to collect old phones for recycling.","meaning":"started a new activity","wrongMeanings":["ended an old activity","delayed a new activity","refused a new activity"]},{"contextId":"u8_19_launched_paraphrase","text":"The café launched a new menu last month, and sales have doubled.","meaning":"introduced for the first time","wrongMeanings":["removed after a short time","copied from a rival","reduced in price"]}],"situationDistractors":["A shop stopped selling a sweet that nobody bought.","A factory closed down after fifty years.","A company took an old phone off the market.","A manager cancelled a project before it began.","A designer threw away her first drawings.","A café removed a dish from its menu."],"gapDistractors":[{"contextId":"u8_19_launched_gap_1","answer":"launched","wrong":["concerned","qualified","detailed"]},{"contextId":"u8_19_launched_gap_2","answer":"launched","wrong":["qualified","concerned","curved"]},{"contextId":"u8_19_launched_gap_3","answer":"launched","wrong":["concerned","qualified","curved"]}],"spellingErrors":["lanched","launcht","lawnched","lauched","launchd","launshed"],"masteryPassages":[{"passageId":"u8_19_launched_passage_1","contextId":"u8_19_launched_gap_1","text":"For two years, the designers worked on the new trainers in secret. Finally, the company ____ them at a huge event, and they sold out in a week.","answer":"launched"},{"passageId":"u8_19_launched_passage_2","contextId":"u8_19_launched_gap_2","text":"The town council was worried about litter on the beach. Last summer it ____ a campaign to get visitors to take their rubbish home.","answer":"launched"}],"contextDependentParaphrases":[],"wrongParaphrases":["removed from the shops","hidden from the public","returned to the factory"],"misleadingDistractors":["stopped making and took off sale","repaired and returned to customers","tested secretly in a laboratory"],"teacherNote":"Verb (past tense or past participle): started selling a new product or began a new project or campaign (launched a product, launched a campaign). Boundary: launch can also mean send a rocket or a boat into the air or water; Unit 8 teaches the business sense. The noun and base verb launch share one spelling, so no three-form family is taught."}]'::jsonb,'[]'::jsonb,'["launched a new product","launched a campaign","was officially launched"]'::jsonb,'live'),
('vocab_landscape_8','landscape','noun','everything you can see across an area of land, such as hills, fields and trees','[{"senseId":"landscape_8_1","meaning":"everything you can see across an area of land, such as hills, fields and trees","acceptedParaphrases":["the scenery of an area","the view of the land"],"masteryContexts":[{"contextId":"u8_20_landscape_8_meaning","text":"The new factory was painted green so that it would not spoil the landscape.","meaning":"the scenery of the area","wrongMeanings":["the air quality of the area","the people of the area","the history of the area"]},{"contextId":"u8_20_landscape_8_paraphrase","text":"Gardeners planted trees and built small hills to change the flat landscape around the office.","meaning":"the shape and look of the land","wrongMeanings":["the cost and value of the land","the owners and users of the land","the rules and laws of the land"]}],"situationDistractors":["A worker typed a report in a small office with no windows.","A cook chopped onions in a busy kitchen.","A mechanic changed the oil in a car.","A cleaner hoovered the carpet in a hotel room.","A clerk sorted letters in a post room.","A customer waited in a queue at the bank."],"gapDistractors":[{"contextId":"u8_20_landscape_8_gap_1","answer":"landscape","wrong":["packaging","publicity","wellbeing"]},{"contextId":"u8_20_landscape_8_gap_2","answer":"landscape","wrong":["packaging","manufacturing","employment"]},{"contextId":"u8_20_landscape_8_gap_3","answer":"landscape","wrong":["packaging","publicity","employment"]}],"spellingErrors":["landscap","lanscape","landscpae","landskape","landscaipe","landscaep"],"masteryPassages":[{"passageId":"u8_20_landscape_8_passage_1","contextId":"u8_20_landscape_8_gap_1","text":"From the top of the hill, you can see fields, forests and a long silver river. The ____ is so beautiful that artists come here to paint it.","answer":"landscape"},{"passageId":"u8_20_landscape_8_passage_2","contextId":"u8_20_landscape_8_gap_2","text":"The architect did not want her new hotel to spoil the view. She used stone and wood so that the building would blend into the surrounding ____.","answer":"landscape"}],"contextDependentParaphrases":[],"wrongParaphrases":["the history of an area","the weather of an area","the population of an area"],"misleadingDistractors":["the buildings in the centre of a city","a map that shows roads and towns","the weather in a particular region"],"teacherNote":"Noun: everything you can see across an area of land (a rural landscape, the landscape around a building). Unit 8 uses it for designers who plan buildings and gardens to fit their surroundings; Unit 4 taught the same core sense for travel. No family is taught."}]'::jsonb,'[]'::jsonb,'["a beautiful landscape","the natural landscape","spoil the landscape"]'::jsonb,'live')
